//! Index only UUIDs generated by NextChat, and remove only their transcript files.
use serde::{Deserialize, Serialize};
use std::collections::HashSet;
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, OnceLock};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const RETENTION: Duration = Duration::from_secs(7 * 24 * 60 * 60);
const MAX_SESSIONS: usize = 100;

#[derive(Serialize, Deserialize)]
struct Record {
    id: String,
    pid: u32,
    used: u64,
    #[serde(default)]
    owner: String,
}

// A second runtime in this process can share the same index. Keep one lock
// and active set for every runtime, including while a transcript is removed.
fn active_sessions() -> &'static Mutex<HashSet<PathBuf>> {
    static ACTIVE: OnceLock<Mutex<HashSet<PathBuf>>> = OnceLock::new();
    ACTIVE.get_or_init(|| Mutex::new(HashSet::new()))
}

fn uuid(id: &str) -> bool {
    let b = id.as_bytes();
    b.len() == 36
        && [8, 13, 18, 23].iter().all(|i| b[*i] == b'-')
        && b[14] == b'4'
        && b"89ab".contains(&b[19])
        && b.iter().enumerate().all(|(i, c)| {
            [8, 13, 18, 23].contains(&i) || c.is_ascii_digit() || (b'a'..=b'f').contains(c)
        })
}
fn now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
fn linked(meta: &fs::Metadata) -> bool {
    #[cfg(windows)]
    {
        use std::os::windows::fs::MetadataExt;
        meta.file_attributes() & 0x400 != 0
    }
    #[cfg(not(windows))]
    {
        meta.file_type().is_symlink()
    }
}
fn safe_dir(path: &Path) -> bool {
    fs::symlink_metadata(path).map_or(false, |m| m.is_dir() && !linked(&m))
}

pub struct OwnedSessions {
    index: PathBuf,
    config: PathBuf,
    project: PathBuf,
    owner: String,
}
impl OwnedSessions {
    pub fn new(index: PathBuf, work: &Path) -> Result<Arc<Self>, String> {
        #[cfg(windows)]
        let home = std::env::var_os("USERPROFILE");
        #[cfg(not(windows))]
        let home = std::env::var_os("HOME");
        let home = home.ok_or("Cannot locate Claude Code history directory")?;
        Self::with_config(index, work, PathBuf::from(home).join(".claude"))
    }
    fn with_config(index: PathBuf, work: &Path, config: PathBuf) -> Result<Arc<Self>, String> {
        fs::create_dir_all(&index).map_err(|_| "Cannot prepare subscription session index")?;
        if !safe_dir(&index) {
            return Err("Invalid subscription session index".into());
        }
        let index = fs::canonicalize(index).map_err(|_| "Invalid subscription session index")?;
        let canonical =
            fs::canonicalize(work).map_err(|_| "Cannot inspect subscription working directory")?;
        let path = dunce::simplified(&canonical).to_string_lossy();
        let slug: String = path
            .encode_utf16()
            .map(|c| {
                if c <= 127 && (c as u8).is_ascii_alphanumeric() {
                    char::from(c as u8)
                } else {
                    '-'
                }
            })
            .collect();
        let project = config.join("projects").join(slug);
        Ok(Arc::new(Self {
            index,
            config,
            project,
            owner: crate::claude_cli::random_uuid()?,
        }))
    }
    fn read(&self, id: &str) -> Option<Record> {
        if !uuid(id) {
            return None;
        }
        let path = self.index.join(format!("{id}.json"));
        let meta = fs::symlink_metadata(&path).ok()?;
        if linked(&meta) || !meta.is_file() || meta.len() > 4096 {
            return None;
        }
        let record: Record = serde_json::from_slice(&fs::read(path).ok()?).ok()?;
        (record.id == id && record.pid > 0).then_some(record)
    }
    fn write(&self, record: &Record, create: bool) -> Result<(), String> {
        let mut file = tempfile::NamedTempFile::new_in(&self.index)
            .map_err(|_| "Cannot write subscription session index")?;
        file.write_all(
            &serde_json::to_vec(record).map_err(|_| "Cannot encode subscription session index")?,
        )
        .map_err(|_| "Cannot write subscription session index")?;
        let destination = self.index.join(format!("{}.json", record.id));
        if create {
            file.persist_noclobber(destination)
                .map_err(|_| "Cannot save subscription session index")?;
        } else {
            file.persist(destination)
                .map_err(|_| "Cannot save subscription session index")?;
        }
        Ok(())
    }
    fn active_key(&self, id: &str) -> PathBuf {
        self.index.join(format!("{id}.json"))
    }
    pub fn begin(self: &Arc<Self>, id: &str) -> Result<OwnedLease, String> {
        if !uuid(id) {
            return Err("Invalid subscription session identity".into());
        }
        let mut active = active_sessions()
            .lock()
            .map_err(|_| "Subscription session state unavailable")?;
        if active.contains(&self.active_key(id)) {
            return Err("Subscription session already active".into());
        }
        let record = self.read(id);
        if record.as_ref().map_or(false, |r| {
            r.pid != std::process::id() || r.owner != self.owner
        }) {
            return Err("Subscription session identity is already owned".into());
        }
        if record.is_none() {
            if fs::symlink_metadata(self.index.join(format!("{id}.json"))).is_ok() {
                return Err("Invalid subscription session record".into());
            }
            if fs::symlink_metadata(self.project.join(format!("{id}.jsonl"))).is_ok() {
                return Err("Subscription session identity already exists".into());
            }
        }
        self.write(
            &Record {
                id: id.into(),
                pid: std::process::id(),
                used: now(),
                owner: self.owner.clone(),
            },
            record.is_none(),
        )?;
        active.insert(self.active_key(id));
        Ok(OwnedLease {
            owner: self.clone(),
            id: id.into(),
        })
    }
    fn end(&self, id: &str) {
        if let Ok(mut active) = active_sessions().lock() {
            if let Some(mut record) = self.read(id) {
                if record.owner == self.owner {
                    record.used = now();
                    let _ = self.write(&record, false);
                }
            }
            active.remove(&self.active_key(id));
            self.sweep_locked(&active, MAX_SESSIONS, RETENTION);
        }
    }
    fn sweep_locked(&self, active: &HashSet<PathBuf>, max: usize, retention: Duration) {
        let Ok(entries) = fs::read_dir(&self.index) else {
            return;
        };
        let mut records: Vec<Record> = entries
            .flatten()
            .filter_map(|entry| {
                let name = entry.file_name();
                let id = name.to_str()?.strip_suffix(".json")?;
                self.read(id)
            })
            .collect();
        records.sort_by_key(|r| r.used);
        let mut remaining = records.len();
        for record in records {
            if now().saturating_sub(record.used) <= retention.as_secs() && remaining <= max {
                continue;
            }
            if active.contains(&self.active_key(&record.id))
                || (record.pid != std::process::id()
                    && crate::claude_cli_sessions::process_alive(record.pid))
            {
                continue;
            }
            if self.discard(&record.id) {
                remaining -= 1;
            }
        }
    }
    fn discard(&self, id: &str) -> bool {
        if !uuid(id)
            || !safe_dir(&self.config)
            || !safe_dir(&self.config.join("projects"))
            || !safe_dir(&self.project)
        {
            return false;
        }
        let path = self.project.join(format!("{id}.jsonl"));
        match fs::symlink_metadata(&path) {
            Ok(meta) if meta.is_file() && !linked(&meta) => {
                if fs::remove_file(path).is_err() {
                    return false;
                }
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            _ => return false,
        }
        let _ = fs::remove_file(self.index.join(format!("{id}.json")));
        true
    }

    #[cfg(test)]
    pub(crate) fn cleanup_test_sessions(&self) -> Result<(), String> {
        let active = active_sessions()
            .lock()
            .map_err(|_| "Session state unavailable")?;
        for entry in fs::read_dir(&self.index).map_err(|_| "Cannot read test session index")? {
            let entry = entry.map_err(|_| "Cannot read test session index")?;
            let name = entry.file_name();
            let Some(id) = name.to_str().and_then(|name| name.strip_suffix(".json")) else {
                continue;
            };
            let Some(record) = self.read(id) else {
                continue;
            };
            if record.owner != self.owner
                || active.contains(&self.active_key(id))
                || !self.discard(id)
            {
                return Err("Cannot safely clean a test-owned Claude session".into());
            }
        }
        Ok(())
    }
}
pub struct OwnedLease {
    owner: Arc<OwnedSessions>,
    id: String,
}
impl Drop for OwnedLease {
    fn drop(&mut self) {
        self.owner.end(&self.id);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn cleanup_removes_only_indexed_transcript_in_owned_project() {
        let temp = tempfile::tempdir().unwrap();
        let work = temp.path().join("work");
        let config = temp.path().join("config");
        fs::create_dir_all(&work).unwrap();
        let registry =
            OwnedSessions::with_config(temp.path().join("index"), &work, config).unwrap();
        fs::create_dir_all(&registry.project).unwrap();
        let id = "1251b7de-4896-4d98-b4de-3b1cc439d897";
        let lease = registry.begin(id).unwrap();
        let owned = registry.project.join(format!("{id}.jsonl"));
        let unrelated = registry.project.join("unrelated.jsonl");
        fs::write(&owned, "test").unwrap();
        fs::write(&unrelated, "keep").unwrap();
        drop(lease);
        registry.sweep_locked(&HashSet::new(), 0, Duration::ZERO);
        assert!(!owned.exists());
        assert_eq!(fs::read_to_string(unrelated).unwrap(), "keep");
    }
    #[test]
    fn another_registry_in_this_process_cannot_delete_an_active_session() {
        let temp = tempfile::tempdir().unwrap();
        let work = temp.path().join("work");
        let config = temp.path().join("config");
        fs::create_dir_all(&work).unwrap();
        let first =
            OwnedSessions::with_config(temp.path().join("index"), &work, config.clone()).unwrap();
        let second = OwnedSessions::with_config(temp.path().join("index"), &work, config).unwrap();
        fs::create_dir_all(&first.project).unwrap();
        let id = "1251b7de-4896-4d98-b4de-3b1cc439d897";
        let lease = first.begin(id).unwrap();
        let transcript = first.project.join(format!("{id}.jsonl"));
        fs::write(&transcript, "active").unwrap();
        {
            let active = active_sessions().lock().unwrap();
            second.sweep_locked(&active, 0, Duration::ZERO);
        }
        assert_eq!(fs::read_to_string(&transcript).unwrap(), "active");
        drop(lease);
    }
    #[cfg(windows)]
    #[test]
    fn cleanup_refuses_linked_project_directory() {
        let temp = tempfile::tempdir().unwrap();
        let work = temp.path().join("work");
        let config = temp.path().join("config");
        let outside = temp.path().join("outside");
        fs::create_dir_all(&work).unwrap();
        fs::create_dir_all(config.join("projects")).unwrap();
        fs::create_dir_all(&outside).unwrap();
        let registry =
            OwnedSessions::with_config(temp.path().join("index"), &work, config).unwrap();
        if std::os::windows::fs::symlink_dir(&outside, &registry.project).is_err() {
            return; // Symlink creation can require Windows developer mode.
        }
        let id = "1251b7de-4896-4d98-b4de-3b1cc439d897";
        let lease = registry.begin(id).unwrap();
        let transcript = outside.join(format!("{id}.jsonl"));
        fs::write(&transcript, "keep").unwrap();
        drop(lease);
        {
            let active = active_sessions().lock().unwrap();
            registry.sweep_locked(&active, 0, Duration::ZERO);
        }
        assert_eq!(fs::read_to_string(transcript).unwrap(), "keep");
    }
}
